// PinnedSession.swift
// Beacon
//
// URLSession configured with certificate pinning against the private Beacon CA.
//
// Trust model:
//   1. The chain is validated with the CA certificate bundled in the app
//      (Resources/ca.crt, generated by `beacon tls init`) as the only anchor — the system
//      trust store is not used, so a public CA cannot impersonate this server.
//   2. If a pin is configured (base64url SHA-256 of the server certificate's
//      SubjectPublicKeyInfo, printed by `beacon tls show`), the leaf SPKI must match it.
//
// There is deliberately no "accept any certificate" path.

import Foundation
import CryptoKit
import Security

/// Computes the SPKI pin of a certificate by walking the DER structure of
/// `Certificate ::= SEQUENCE { tbsCertificate, signatureAlgorithm, signatureValue }`.
enum SPKIPin {
    static func base64URLPin(for certificate: SecCertificate) -> String? {
        let der = SecCertificateCopyData(certificate) as Data
        guard let spki = subjectPublicKeyInfo(in: [UInt8](der)) else { return nil }
        let digest = SHA256.hash(data: Data(spki))
        return base64URL(Data(digest))
    }

    static func base64URL(_ data: Data) -> String {
        data.base64EncodedString()
            .replacingOccurrences(of: "+", with: "-")
            .replacingOccurrences(of: "/", with: "_")
            .replacingOccurrences(of: "=", with: "")
    }

    static func subjectPublicKeyInfo(in der: [UInt8]) -> [UInt8]? {
        var reader = DERReader(bytes: der)
        guard let certificate = reader.readTLV(), certificate.tag == 0x30 else { return nil }
        var tbsReader = DERReader(bytes: Array(certificate.content))
        guard let tbs = tbsReader.readTLV(), tbs.tag == 0x30 else { return nil }
        var fields = DERReader(bytes: Array(tbs.content))

        // Optional [0] EXPLICIT version.
        guard fields.peekTag() != nil else { return nil }
        if fields.peekTag() == 0xA0 {
            guard fields.skipTLV() else { return nil }
        }
        // serialNumber INTEGER, signature AlgorithmIdentifier SEQUENCE,
        // issuer Name SEQUENCE, validity SEQUENCE, subject Name SEQUENCE.
        for _ in 0..<5 {
            guard fields.skipTLV() else { return nil }
        }
        guard let spki = fields.readTLV(), spki.tag == 0x30 else { return nil }
        return spki.full
    }
}

private struct DERReader {
    let bytes: [UInt8]
    var index: Int = 0

    struct TLV {
        let tag: UInt8
        let full: [UInt8]
        let content: [UInt8]
    }

    mutating func peekTag() -> UInt8? {
        guard index < bytes.count else { return nil }
        return bytes[index]
    }

    mutating func skipTLV() -> Bool {
        readTLV() != nil
    }

    mutating func readTLV() -> TLV? {
        guard index + 2 <= bytes.count else { return nil }
        let start = index
        let tag = bytes[index]
        index += 1
        guard let length = readLength() else { return nil }
        guard index + length <= bytes.count else { return nil }
        let content = Array(bytes[index..<(index + length)])
        index += length
        return TLV(tag: tag, full: Array(bytes[start..<index]), content: content)
    }

    private mutating func readLength() -> Int? {
        guard index < bytes.count else { return nil }
        let first = bytes[index]
        index += 1
        if first & 0x80 == 0 {
            return Int(first)
        }
        let count = Int(first & 0x7F)
        guard count > 0, count <= 4, index + count <= bytes.count else { return nil }
        var value = 0
        for _ in 0..<count {
            value = (value << 8) | Int(bytes[index])
            index += 1
        }
        return value
    }
}

final class PinnedSessionDelegate: NSObject, URLSessionDelegate {
    private let pin: String?
    private let host: String?
    private let anchors: [SecCertificate]

    init(pin: String?, host: String?) {
        self.pin = pin
        self.host = host
        self.anchors = Self.bundledAnchors()
        super.init()
    }

    private static func bundledAnchors() -> [SecCertificate] {
        guard let url = Bundle.main.url(forResource: "ca", withExtension: "crt"),
              let pem = try? String(contentsOf: url, encoding: .utf8) else {
            return []
        }
        let base64 = pem
            .split(separator: "\n")
            .filter { !$0.contains("-----") }
            .joined()
        guard let der = Data(base64Encoded: base64, options: .ignoreUnknownCharacters),
              let certificate = SecCertificateCreateWithData(nil, der as CFData) else {
            return []
        }
        return [certificate]
    }

    func urlSession(
        _ session: URLSession,
        didReceive challenge: URLAuthenticationChallenge,
        completionHandler: @escaping (URLSession.AuthChallengeDisposition, URLCredential?) -> Void
    ) {
        guard challenge.protectionSpace.authenticationMethod == NSURLAuthenticationMethodServerTrust,
              let trust = challenge.protectionSpace.serverTrust else {
            completionHandler(.performDefaultHandling, nil)
            return
        }
        guard !anchors.isEmpty else {
            // Without the bundled CA we cannot verify the private server; fail closed.
            completionHandler(.cancelAuthenticationChallenge, nil)
            return
        }
        let policy = SecPolicyCreateSSL(true, (host ?? challenge.protectionSpace.host) as CFString)
        SecTrustSetPolicies(trust, policy)
        SecTrustSetAnchorCertificates(trust, anchors as CFArray)
        SecTrustSetAnchorCertificatesOnly(trust, true)

        var error: CFError?
        guard SecTrustEvaluateWithError(trust, &error) else {
            completionHandler(.cancelAuthenticationChallenge, nil)
            return
        }
        let certificate = (SecTrustCopyCertificateChain(trust) as? [SecCertificate])?.first
        guard let certificate else {
            completionHandler(.cancelAuthenticationChallenge, nil)
            return
        }
        if let pin, !pin.isEmpty {
            guard let actual = SPKIPin.base64URLPin(for: certificate), actual == pin else {
                completionHandler(.cancelAuthenticationChallenge, nil)
                return
            }
        }
        completionHandler(.useCredential, URLCredential(trust: trust))
    }
}

enum PinnedSessionFactory {
    static func make(configuration: ServerConfiguration) -> URLSession {
        let delegate = PinnedSessionDelegate(
            pin: configuration.spkiPin,
            host: configuration.baseURL.host
        )
        let sessionConfiguration = URLSessionConfiguration.ephemeral
        sessionConfiguration.timeoutIntervalForRequest = 20
        sessionConfiguration.timeoutIntervalForResource = 40
        sessionConfiguration.httpAdditionalHeaders = ["Accept": "application/json"]
        sessionConfiguration.waitsForConnectivity = false
        return URLSession(
            configuration: sessionConfiguration,
            delegate: delegate,
            delegateQueue: nil
        )
    }
}
